import openpyxl

path='/root/output/result.xlsx'
wb=openpyxl.load_workbook(path, data_only=False)
ws=wb['Task']

check_cells=['H12','H19','H26','H35','H42','H46','H47','H50']
print('Formula spot-check:')
for addr in check_cells:
    v=ws[addr].value
    print(addr, repr(v))

# Confirm no None/empty in target ranges
ranges=[('H', 'L', 12, 17), ('H','L',19,24), ('H','L',26,31), ('H','L',35,40), ('H','L',42,47), ('H','L',50,50)]

def iter_cells(col_start, col_end, r1, r2):
    for r in range(r1,r2+1):
        for c in range(ord(col_start), ord(col_end)+1):
            addr=f'{chr(c)}{r}'
            yield addr, ws[addr].value

missing=[]
for c1,c2,r1,r2 in ranges:
    for addr,v in iter_cells(c1,c2,r1,r2):
        if v is None or v=='':
            missing.append(addr)

print('\nMissing count:', len(missing))
if missing:
    print('Missing examples:', missing[:20])

# Confirm PERCENTILE usage
bad=[]
for col in ['H','I','J','K','L']:
    for r in [46,47]:
        f=ws[f'{col}{r}'].value
        if isinstance(f,str) and 'PERCENTILE.INC' in f:
            bad.append(f'{col}{r}')
        if not (isinstance(f,str) and f.strip().upper().startswith('=PERCENTILE(')):
            # should start with =PERCENTILE(
            bad.append(f'{col}{r} (not PERCENTILE)')

print('\nPERCENTILE check bad:', bad)
